<?php
require __DIR__.'/inc/auth.php';require_permission('audit.view');require __DIR__.'/inc/forms.php';$page_title='审计日志';
$where='1=1';$params=[];if(!is_super_admin()){$where.=' AND admin_id=?';$params[]=(int)$_SESSION['admin']['id'];}
$action=trim($_GET['action'] ?? '');if($action!==''){$where.=' AND action=?';$params[]=$action;}
foreach(['from'=>'>=','to'=>'<='] as $key=>$op){$date=$_GET[$key] ?? '';if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)){$where.=' AND created_at '.$op.' ?';$params[]=$date.($key==='from'?' 00:00:00':' 23:59:59');}}
$page=max(1,(int)($_GET['page'] ?? 1));$offset=($page-1)*20;$count=(int)one('SELECT COUNT(*) n FROM admin_audit_logs WHERE '.$where,$params)['n'];$logs=rows('SELECT * FROM admin_audit_logs WHERE '.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.$offset,$params);
require __DIR__.'/inc/header.php'; ?><h1>审计日志</h1><p><?=is_super_admin()?'查看全平台操作记录':'仅显示你本人操作的记录'?></p><form><input name="action" value="<?=h($action)?>" placeholder="操作标识"><input type="date" name="from" value="<?=h($_GET['from'] ?? '')?>"><input type="date" name="to" value="<?=h($_GET['to'] ?? '')?>"><button>筛选</button></form><table class="crud-table"><tr><th>时间 / 管理员</th><th>操作 / 对象</th><th>结果</th><th>详情 / 来源</th></tr><?php foreach($logs as $l): ?><tr><td><?=h($l['created_at'])?><br><?=h($l['username'])?></td><td><?=h($l['action'])?><br><?=h($l['target_type'])?> <?=h($l['target_id'])?></td><td><?=h($l['status'])?></td><td><?=h($l['detail'])?><br><?=h($l['ip'])?></td></tr><?php endforeach; ?></table><?php admin_pagination($page,$count);require __DIR__.'/inc/footer.php'; ?>
